#[test]
fn sqlite_snapshot_avi_manual_variant_metadata_retains_neutral_choices_under_both_controls(){
 let semio_framework_dsl_record::BorrowedShape::Statements(variants)=<AviStreamFormat as semio_framework_dsl_record::BorrowedDslField>::SHAPE else{panic!("AVI choice statements")};let borrowed:Vec<_>=variants.iter().map(|(name,record)|serde_json::json!([name,record().fields.len()])).collect();let neutral:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️schema/📸️snapshot/🧫️fixtures/🏭️schema/🔣️.json")).unwrap();assert_eq!(serde_json::json!(borrowed),neutral["variants"]);
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️schema/📸️snapshot/🧫️fixtures/🏭️schema/🔣️.json")).unwrap();let maximum=fixture["maximumBytes"].as_u64().unwrap()as usize;let tiny=fixture["tinyBytes"].as_u64().unwrap()as usize;
 let mut admitted=|_|true;let mut encoding=semio_framework_value::NativeEncodeControl::new(maximum,&mut admitted);let semio_framework_dsl_record::Shape::Statements(encoded)=<AviStreamFormat as semio_framework_dsl_record::DslField>::shape_controlled(&mut encoding).unwrap()else{panic!("declared choices")};let mut output=Vec::new();for(keyword,producer)in &encoded{let record=producer.encode(&mut encoding).unwrap();output.push(serde_json::json!([keyword,record.fields.len()]));}assert_eq!(serde_json::json!(output),fixture["variants"]);let exact=encoding.owned_bytes();assert!(exact>0);
 let mut admitted=|_|true;let mut decoding=semio_framework_value::NativeDecodeControl::new(maximum,&mut admitted);let semio_framework_dsl_record::Shape::Statements(decoded)=<AviStreamFormat as semio_framework_dsl_record::DslField>::shape_controlled(&mut decoding).unwrap()else{panic!("declared choices")};let mut output=Vec::new();for(keyword,producer)in &decoded{let record=producer.decode(&mut decoding).unwrap();output.push(serde_json::json!([keyword,record.fields.len()]));}assert_eq!(serde_json::json!(output),fixture["variants"]);
 let mut admitted=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(tiny,&mut admitted);assert!(<AviStreamFormat as semio_framework_dsl_record::DslField>::shape_controlled(&mut control).is_err());assert_eq!(control.owned_bytes(),0);assert!(<AviStreamFormat as semio_framework_dsl_record::DslField>::shape_controlled(&mut semio_framework_value::NativeDecodeControl::new(tiny,&mut |_|true)).is_err());assert!(<AviStreamFormat as semio_framework_dsl_record::DslField>::shape_controlled(&mut semio_framework_value::NativeEncodeControl::new(maximum,&mut |_|false)).is_err());assert!(<AviStreamFormat as semio_framework_dsl_record::DslField>::shape_controlled(&mut semio_framework_value::NativeDecodeControl::new(maximum,&mut |_|false)).is_err());
}
#[test]
fn sqlite_snapshot_avi_controlled_native_owner_preserves_full_fixture_and_enforces_caller_limits(){
 use semio_framework_os_kernel::{io::IoPayload,sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl},ArtifactSqliteSnapshot};
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 for payload in[IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))]{
  assert_eq!(AviSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),snapshot);
  assert!(AviSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
  assert!(AviSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());
  assert!(AviSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1,..limits})).is_err());
 }
}
#[test]
fn sqlite_snapshot_avi_authored_grammar_and_protocol_admit_complete_records() {
    let grammar = semio_framework_dsl::parse_grammar(include_str!("../../../📝️text/📸️snapshot/📖️.grammar.semio")).unwrap();
    let recognizer = semio_framework_dsl::Recognizer::compile(&grammar, &semio_framework_os_kernel::os_dsl::grammar::family_fragments().expect("OS family grammar"), semio_framework_os_kernel::os_dsl::grammar::product_macros()).expect("selected grammar fragments");
    let demo = crate::standards::v1_0::subsets::any::io::decode_avi(include_bytes!("../../../../📚️examples/🎬️demo/🖼️assets/🎬️.avi")).unwrap();
    for snapshot in [fixture(), AviSnapshot::default(), demo] {
        let text = <AviSnapshot as store::ArtifactDsl>::print_dsl(&snapshot);
        let (_, body) = store::semio_format::split_text_preamble(&text).unwrap();
        assert!(recognizer.recognize(body).unwrap(), "{body}");
    }
    let protocol = semio_framework_dsl::parse_protocol(include_str!("../../../💾️binary/📸️snapshot/📡️.protocol.semio")).unwrap();
    assert_eq!(protocol.schema, "stdio.avi");
    assert_eq!(protocol.version, 1);
    assert_eq!(protocol.blocks.iter().filter(|block| matches!(block, semio_framework_dsl::Block::Record { .. })).count(), 9);
}
