#[test]
fn sqlite_snapshot_avi_independent_sqlite_joins_and_complete_retained_edits(){use std::{io::Write,process::{Command,Stdio}};let mut expected=fixture();let database=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import {Database} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const row=db.query('SELECT h.rc_frame_width,h.quality,b.width,b.colors_important FROM avi_stream s JOIN avi_stream_header h ON h.id=s.id JOIN avi_bitmap_info b ON b.id=s.id').get();if(row.rc_frame_width!==255||row.quality!==-2147483648||row.width!==-2147483648||row.colors_important!==4294967295)throw Error('domain');if(db.query('SELECT channels FROM avi_wave_format').get().channels!==65535||db.query('SELECT hex(data) AS bytes FROM avi_raw_format').get().bytes!=='00FF2A')throw Error('choices');db.run(\"UPDATE avi_stream_header SET quality=-123,strh_extra=X'00FF' WHERE id=1\");db.run(\"UPDATE avi_bitmap_info SET width=88 WHERE id=1\");db.run(\"UPDATE avi_stream_extra SET fourcc='edited 世界' WHERE id=1\");db.run('UPDATE avi_stream_chunk SET keyframe=0 WHERE id=1');db.run('UPDATE avi_main_reserved SET value=99 WHERE ordinal=4');await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.streams[0].strh.quality=-123;expected.streams[0].strh.strh_extra=vec![0,255];if let AviStreamFormat::BitmapInfo{width,..}=&mut expected.streams[0].strf{*width=88;}expected.streams[0].strl_extra[0].fourcc="edited 世界".into();expected.streams[0].chunks[0].keyframe=false;expected.main_header.reserved[4]=99;assert_eq!(AviSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);}
#[test]
fn sqlite_snapshot_avi_refuses_invalid_owners_ordinals_choices_widths_and_limits(){let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for(table,column,value)in[("avi_stream",1,SqliteValue::Integer(99)),("avi_stream",2,SqliteValue::Integer(99)),("avi_stream",3,SqliteValue::Text("raw".into())),("avi_stream_chunk",1,SqliteValue::Integer(99)),("avi_stream_chunk",2,SqliteValue::Integer(99)),("avi_stream_chunk",5,SqliteValue::Integer(2)),("avi_stream_header",4,SqliteValue::Integer(65536)),("avi_stream_header",18,SqliteValue::Integer(256)),("avi_main_header",1,SqliteValue::Integer(4294967296)),("avi_bitmap_info",2,SqliteValue::Integer(-2147483649))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(AviSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}for table in["avi_main_header","avi_stream_header","avi_bitmap_info"]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows.clear();assert!(AviSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());assert!(AviSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:0,..SqliteDatabaseLimits::default()})).is_err());}
