fn sqlite_snapshot_avi_large_intrinsic_copy_and_entities_remain_cancellable(){let controls:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎛️control.json")).unwrap();let mut snapshot=fixture();snapshot.streams[0].chunks=vec![snapshot.streams[0].chunks[0].clone();controls["entityCount"].as_u64().unwrap() as usize];let cancel_at=controls["cancelAt"].as_u64().unwrap() as usize;let mut reached=false;assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |event|{if event.completed>=cancel_at{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);snapshot=fixture();snapshot.streams[0].strh.strh_extra=vec![255;controls["largeBlobBytes"].as_u64().unwrap() as usize];let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>0&&event.total==0{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{AviSnapshot::from_sqlite_database(&database,&mut control).is_err()});assert!(reached);}}
